transforms.result:
.app-googles {
  &__photo-googles {
    position: absolute;
    // top: 270px;
    // left: 85px;
    top: 190px;
    // left: 84px;
    left: 56px;
    top: 270px;
    left: 270px;
    cursor: pointer;
    z-index: 5;
    @media (hover: none) {
      display: none;
      z-index: -1;
    }

    @media screen and (max-width: $desktop) {
      left: 84px;
    }
    @media screen and (max-width: $tablet) {
      left: 78px;
    }
    @media screen and (max-width: $mobile) {
      left: 70px;
    }

    @media screen and (max-width: 347px) {
      // top: 228px;
      left: 70px;
    }
    @media screen and (max-width: 329px) {
      top: 308px;
    }
  }
  &__mobile-googles {
    display: none;
    position: absolute;
    top: 270px;
    left: 85px;
    cursor: pointer;
    z-index: -1;
    @media (hover: none) {
      display: block;
      z-index: 5;
    }
    @media screen and (max-width: $tablet) {
      left: 78px;
    }
    @media screen and (max-width: $mobile) {
      left: 70px;
    }
    @media screen and (max-width: 338px) {
      top: 310px;
      left: 70px;
    }
  }
  &__googles-svg {
    width: 90px;
  }
}
.night-glasses {
  fill: #f6e49c88;
  color: #f6e49c88;
  transition: color, fill ease 1s 1s;
}
.sun-glasses {
  fill: #00003fdf;
  color: #00003fdf;
  transition: color, fill ease 1s 1s;
}
